-- =====================================================================

SET NAMES utf8mb4;

-- =====================================================================
-- 一、ALTER TABLE 添加8个缺失的吉庆词列
-- =====================================================================
-- 添加成人吉庆词列
ALTER TABLE dish_master ADD COLUMN adult_name varchar(100) DEFAULT NULL COMMENT '成人吉庆词' AFTER baby_born_name;
-- 添加谢师吉庆词列
ALTER TABLE dish_master ADD COLUMN teacher_name varchar(100) DEFAULT NULL COMMENT '谢师吉庆词' AFTER baby_born_name;
-- 添加战友吉庆词列
ALTER TABLE dish_master ADD COLUMN comrade_name varchar(100) DEFAULT NULL COMMENT '战友吉庆词' AFTER baby_born_name;
-- 添加开张吉庆词列
ALTER TABLE dish_master ADD COLUMN opening_name varchar(100) DEFAULT NULL COMMENT '开张吉庆词' AFTER baby_born_name;
-- 添加庆功吉庆词列
ALTER TABLE dish_master ADD COLUMN victory_name varchar(100) DEFAULT NULL COMMENT '庆功吉庆词' AFTER baby_born_name;
-- 添加升学吉庆词列
ALTER TABLE dish_master ADD COLUMN school_name varchar(100) DEFAULT NULL COMMENT '升学吉庆词' AFTER baby_born_name;
-- 添加迎春吉庆词列
ALTER TABLE dish_master ADD COLUMN spring_name varchar(100) DEFAULT NULL COMMENT '迎春吉庆词' AFTER baby_born_name;
-- 添加商务吉庆词列
ALTER TABLE dish_master ADD COLUMN business_name varchar(100) DEFAULT NULL COMMENT '商务吉庆词' AFTER baby_born_name;

