SELECT '=== 吉庆词列数据统计 ===' AS info;
SELECT COUNT(*) AS total_dishes,
  COUNT(birthday_name) AS birthday,
  COUNT(wedding_name) AS wedding,
  COUNT(house_move_name) AS house_move,
  COUNT(promotion_name) AS promotion,
  COUNT(reunion_name) AS reunion,
  COUNT(thanksgiving_name) AS thanksgiving,
  COUNT(year_end_name) AS year_end,
  COUNT(baby_born_name) AS baby_born,
  COUNT(adult_name) AS adult,
  COUNT(teacher_name) AS teacher,
  COUNT(comrade_name) AS comrade,
  COUNT(opening_name) AS opening,
  COUNT(victory_name) AS victory,
  COUNT(school_name) AS school,
  COUNT(spring_name) AS spring,
  COUNT(business_name) AS business
FROM dish_master WHERE dish_id LIKE 'CY%';
